package com.scriptles.cabinet.profile.entity;
import com.scriptles.cabinet.profile.enums.HQMemberRole; import com.scriptles.cabinet.user.entity.User; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="hq_members",uniqueConstraints=@UniqueConstraint(name="uk_hq_member_account",columnNames={"hq_profile_id","account_id"})) @Getter @Setter @NoArgsConstructor
public class HQMember { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="hq_profile_id",nullable=false) private HQProfile hqProfile; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id",nullable=false) private User account; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private HQMemberRole role; @CreationTimestamp private Instant createdAt; }
